/**
 * Writes scripts/data/iqvia-alternative-uae-primary-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-iqvia-uae-primary-research-cover.mjs.
 *
 *   node scripts/generate-iqvia-uae-primary-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/iqvia-alternative-uae-primary-research.json');

export const LAURA_MCCONAUGHEY_SANITY_ID = '5373a02d-e67d-4415-9739-33ee8f4da7e2';

/** Every blogPost field that applies to a healthcare-silo article. */
export const IQVIA_UAE_PRIMARY_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-iqvia-alternative-uae-primary-research.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.IQVIA_UAE_PRIMARY_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.IQVIA_UAE_PRIMARY_BODY_HTML.split('<h2')[0])
    .replace(
      /^IQVIA alternative UAE primary research[\s\S]*?It does not ask anyone to drop IQVIA\./,
      '',
    )
    .trim();

  return {
    seo: {
      metaTitle: mod.IQVIA_UAE_PRIMARY_META_TITLE,
      metaDescription: mod.IQVIA_UAE_PRIMARY_META_DESCRIPTION,
      focusKeyword: 'IQVIA alternative UAE primary research',
      keywords: [
        'IQVIA alternative UAE primary research',
        'syndicated vs custom pharma research UAE',
        'UAE primary market research',
        'keep IQVIA add primary research',
        'UAE pharmaceutical audit',
        'Dubai physician survey',
        'Abu Dhabi payer research',
        'UAE market access research',
      ],
      canonicalUrl: mod.IQVIA_UAE_PRIMARY_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.IQVIA_UAE_PRIMARY_META_TITLE,
      ogDescription: mod.IQVIA_UAE_PRIMARY_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.IQVIA_UAE_PRIMARY_COVER_IMAGE}`,
        alt: mod.IQVIA_UAE_PRIMARY_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.IQVIA_UAE_PRIMARY_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.IQVIA_UAE_PRIMARY_SLUG },
    excerpt: mod.IQVIA_UAE_PRIMARY_EXCERPT,
    publishedAt: mod.IQVIA_UAE_PRIMARY_PUBLISHED_ISO,
    updatedAt: mod.IQVIA_UAE_PRIMARY_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: LAURA_MCCONAUGHEY_SANITY_ID,
      name: 'Laura McConaughey',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.IQVIA_UAE_PRIMARY_HERO_IMAGE}`,
      alt: mod.IQVIA_UAE_PRIMARY_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for IQVIA alternative UAE primary research',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.IQVIA_UAE_PRIMARY_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.IQVIA_UAE_PRIMARY_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.IQVIA_UAE_PRIMARY_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.IQVIA_UAE_PRIMARY_EXECUTIVE_SUMMARY_HTML}\n\n${mod.IQVIA_UAE_PRIMARY_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'How UAE brand teams combine syndicated audits with custom primary research',
        type: 'table',
        data: JSON.stringify(
          mod.IQVIA_UAE_PRIMARY_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'IQVIA 2025 10-K; UAE Legislation 28/2023 and 38/2024; MOHAP Statistical Annual Report 2023',
      },
      portableText(
        firstParagraph ||
          'IQVIA alternative UAE primary research is the custom work a brand team commissions after it already has a syndicated audit.',
      ),
    ],
    faq: mod.IQVIA_UAE_PRIMARY_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['uae-healthcare-market-trends-2026', 'gcc-pharmacoeconomics'],
    ctaSection: { ...mod.IQVIA_UAE_PRIMARY_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.IQVIA_UAE_PRIMARY_BODY_HTML),
    factCheckedAt: mod.IQVIA_UAE_PRIMARY_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/iqvia-alternative-uae-primary-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of IQVIA_UAE_PRIMARY_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`,
  );
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
